function Form() {
  const [isIdle, setIsIdle] = useState(true);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isSuccess, setIsSuccess] = useState(false);
  const [isError, setIsError] = useState(false);

  const handleSubmit = async () => {
    setIsIdle(false);
    setIsSubmitting(true);
    try {
      await api.submit();
      setIsSubmitting(false);
      setIsSuccess(true); // Who sets isError to false?
    } catch (e) {
      setIsSubmitting(false);
      setIsError(true); // Who sets isSuccess to false?
    }
  };

  if (isSubmitting) return <Spinner />;
  if (isSuccess) return <Success />;
  if (isError) return <Error />;
  return <Form onSubmit={handleSubmit} />;
}

type State = 'idle' | 'submitting' | 'success' | 'error';

interface Machine<S, E> {
  state: S;
  transition(event: E): Machine<S, E>;
}

class FormMachine implements Machine<State, FormEvent> {
  state: State = 'idle';

  transition(event: FormEvent): FormMachine {
    switch (this.state) {
      case 'idle':
        if (event.type === 'SUBMIT') {
          return { ...this, state: 'submitting' };
        }
        break;
      case 'submitting':
        if (event.type === 'RESOLVE') {
          return { ...this, state: 'success' };
        }
        if (event.type === 'REJECT') {
          return { ...this, state: 'error' };
        }
        break;
    }
    return this;
  }
}

